//! The Unicode rules of v1 validity (ADR 0010, A3 addendum), pinned to
//! one Unicode version through tables generated by `tools/unicode/gen.py`
//! (`unicode_tables.rs`). The Python verifier embeds the same tables, so
//! both sides apply the same version whatever their runtime's own.
//!
//! - Titles and blob names: no character of [`is_text_forbidden`].
//! - Tags: every label (separators `.` `/` `:`) is an IDNA2008 U-label
//!   (RFC 5891 §5.4, RFC 5892, RFC 5893) already in NFC, of one script
//!   (UTS #39 highly restrictive). See [`tag_error`].

use std::borrow::Cow;

use crate::unicode_tables as t;

/// The pinned Unicode version: "unassigned" means unassigned in it.
pub const UNICODE_VERSION: &str = t::UNICODE_VERSION;
/// SHA-256 of the generated tables (the Python verifier's copy has the
/// same).
pub const TABLES_SHA256: &str = t::TABLES_SHA256;
/// Label separators in tags.
pub const TAG_SEPARATORS: [char; 3] = ['.', '/', ':'];
/// Longest label, as an A-label (`xn--` + Punycode for non-ASCII labels).
pub const MAX_A_LABEL_BYTES: usize = 63;

const ZWNJ: u32 = 0x200C;
const ZWJ: u32 = 0x200D;
const VIRAMA: u8 = 9;

// --- Table lookups -----------------------------------------------------------

fn find<T>(table: &[T], cp: u32, range: impl Fn(&T) -> (u32, u32)) -> Option<&T> {
    let i = table.partition_point(|e| range(e).0 <= cp);
    let entry = table.get(i.checked_sub(1)?)?;
    (cp <= range(entry).1).then_some(entry)
}

fn in_ranges(table: &[(u32, u32)], cp: u32) -> bool {
    find(table, cp, |e| *e).is_some()
}

fn value<V: Copy>(table: &[(u32, u32, V)], cp: u32) -> Option<V> {
    find(table, cp, |e| (e.0, e.1)).map(|e| e.2)
}

// --- Titles, blob names, display ----------------------------------------------

/// Not allowed in titles and blob names: general categories Cc, Cf (except
/// ZWNJ and ZWJ), Zl, Zp, Co, Cs and Cn (unassigned in [`UNICODE_VERSION`],
/// noncharacters included).
pub fn is_text_forbidden(c: char) -> bool {
    in_ranges(t::TEXT_FORBIDDEN, c as u32)
}

/// The first character of `s` that [`is_text_forbidden`].
pub fn forbidden_char(s: &str) -> Option<char> {
    s.chars().find(|&c| is_text_forbidden(c))
}

/// Display policy (not validity): format characters (Cf) other than ZWNJ
/// and ZWJ shown as visible escapes such as `\u{202E}`, so that bidi
/// overrides and invisible characters cannot hide anything from a reader.
pub fn escape_format(s: &str) -> Cow<'_, str> {
    let hidden = |c: char| {
        let cp = c as u32;
        cp != ZWNJ && cp != ZWJ && in_ranges(t::FORMAT, cp)
    };
    if !s.chars().any(hidden) {
        return Cow::Borrowed(s);
    }
    let mut out = String::with_capacity(s.len() + 16);
    for c in s.chars() {
        if hidden(c) {
            out.push_str(&format!("\\u{{{:04X}}}", c as u32));
        } else {
            out.push(c);
        }
    }
    Cow::Owned(out)
}

/// A Windows device name, with or without an extension (`nul.txt`): the
/// part before the first dot, without trailing spaces, compared
/// ASCII-case-insensitively with CON, PRN, AUX, NUL, COM0-COM9, LPT0-LPT9
/// and COM/LPT followed by ¹, ² or ³.
pub fn is_windows_reserved(name: &str) -> bool {
    let stem = name
        .split('.')
        .next()
        .unwrap_or_default()
        .trim_end_matches(' ')
        .to_ascii_lowercase();
    if matches!(stem.as_str(), "con" | "prn" | "aux" | "nul") {
        return true;
    }
    let mut chars = stem.chars();
    let prefix: String = chars.by_ref().take(3).collect();
    let rest: Vec<char> = chars.collect();
    matches!(prefix.as_str(), "com" | "lpt")
        && matches!(rest.as_slice(), [c] if c.is_ascii_digit() || matches!(c, '¹' | '²' | '³'))
}

// --- NFC (UAX #15) ---------------------------------------------------------------

const S_BASE: u32 = 0xAC00;
const L_BASE: u32 = 0x1100;
const V_BASE: u32 = 0x1161;
const T_BASE: u32 = 0x11A7;
const L_COUNT: u32 = 19;
const V_COUNT: u32 = 21;
const T_COUNT: u32 = 28;
const N_COUNT: u32 = V_COUNT * T_COUNT;
const S_COUNT: u32 = L_COUNT * N_COUNT;

fn ccc(cp: u32) -> u8 {
    value(t::CCC, cp).unwrap_or(0)
}

fn decompose(s: &str) -> Vec<u32> {
    let mut out = Vec::with_capacity(s.len());
    for c in s.chars() {
        let cp = c as u32;
        if (S_BASE..S_BASE + S_COUNT).contains(&cp) {
            let s = cp - S_BASE;
            out.push(L_BASE + s / N_COUNT);
            out.push(V_BASE + (s % N_COUNT) / T_COUNT);
            if !s.is_multiple_of(T_COUNT) {
                out.push(T_BASE + s % T_COUNT);
            }
        } else if let Ok(i) = t::DECOMPOSITION.binary_search_by_key(&cp, |e| e.0) {
            out.extend_from_slice(t::DECOMPOSITION[i].1);
        } else {
            out.push(cp);
        }
    }
    // Canonical ordering: a stable sort of each run of non-starters.
    let mut i = 0;
    while i < out.len() {
        if ccc(out[i]) == 0 {
            i += 1;
            continue;
        }
        let mut j = i;
        while j < out.len() && ccc(out[j]) != 0 {
            j += 1;
        }
        out[i..j].sort_by_key(|&c| ccc(c));
        i = j;
    }
    out
}

fn compose_pair(a: u32, b: u32) -> Option<u32> {
    if (L_BASE..L_BASE + L_COUNT).contains(&a) && (V_BASE..V_BASE + V_COUNT).contains(&b) {
        return Some(S_BASE + ((a - L_BASE) * V_COUNT + (b - V_BASE)) * T_COUNT);
    }
    if (S_BASE..S_BASE + S_COUNT).contains(&a)
        && (a - S_BASE).is_multiple_of(T_COUNT)
        && (T_BASE + 1..T_BASE + T_COUNT).contains(&b)
    {
        return Some(a + (b - T_BASE));
    }
    t::COMPOSITION
        .binary_search_by(|e| (e.0, e.1).cmp(&(a, b)))
        .ok()
        .map(|i| t::COMPOSITION[i].2)
}

fn compose(cps: Vec<u32>) -> Vec<u32> {
    let mut out: Vec<u32> = Vec::with_capacity(cps.len());
    let mut starter: Option<usize> = None;
    // The ccc of the last character, when it is not the starter.
    let mut last_ccc: Option<u8> = None;
    for cp in cps {
        let c = ccc(cp);
        if let Some(s) = starter
            && last_ccc.is_none_or(|last| last != 0 && last < c)
            && let Some(composed) = compose_pair(out[s], cp)
        {
            out[s] = composed;
            continue;
        }
        if c == 0 {
            starter = Some(out.len());
            last_ccc = None;
        } else {
            last_ccc = Some(c);
        }
        out.push(cp);
    }
    out
}

/// Normalization Form C of `s`, as of [`UNICODE_VERSION`].
pub fn nfc(s: &str) -> String {
    compose(decompose(s))
        .into_iter()
        .filter_map(char::from_u32)
        .collect()
}

/// Whether `s` is already in NFC (exact: by normalizing and comparing).
pub fn is_nfc(s: &str) -> bool {
    nfc(s) == s
}

// --- Tags: IDNA2008 labels -------------------------------------------------------

fn script(cp: u32) -> &'static str {
    value(t::SCRIPT, cp).unwrap_or("Zzzz")
}

fn bidi_class(cp: u32) -> &'static str {
    value(t::BIDI_CLASS, cp).unwrap_or("L")
}

fn joining_type(cp: u32) -> &'static str {
    value(t::JOINING_TYPE, cp).unwrap_or("U")
}

/// RFC 5892 A.1 (ZWNJ) and A.2 (ZWJ).
fn contextj_ok(cps: &[u32], i: usize) -> bool {
    if i > 0 && ccc(cps[i - 1]) == VIRAMA {
        return true;
    }
    if cps[i] != ZWNJ {
        return false;
    }
    let left = cps[..i]
        .iter()
        .rev()
        .map(|&c| joining_type(c))
        .find(|&j| j != "T");
    let right = cps[i + 1..]
        .iter()
        .map(|&c| joining_type(c))
        .find(|&j| j != "T");
    matches!(left, Some("L" | "D")) && matches!(right, Some("R" | "D"))
}

/// RFC 5892 A.3 to A.9.
fn contexto_ok(cps: &[u32], i: usize) -> bool {
    let (cp, n) = (cps[i], cps.len());
    match cp {
        0x00B7 => i > 0 && i + 1 < n && cps[i - 1] == 0x6C && cps[i + 1] == 0x6C,
        0x0375 => i + 1 < n && script(cps[i + 1]) == "Grek",
        0x05F3 | 0x05F4 => i > 0 && script(cps[i - 1]) == "Hebr",
        0x30FB => cps
            .iter()
            .any(|&c| matches!(script(c), "Hira" | "Kana" | "Hani")),
        0x0660..=0x0669 => !cps.iter().any(|c| (0x06F0..=0x06F9).contains(c)),
        0x06F0..=0x06F9 => !cps.iter().any(|c| (0x0660..=0x0669).contains(c)),
        _ => false,
    }
}

/// RFC 3492 Punycode, as used in A-labels (without `xn--`).
pub fn punycode(input: &str) -> String {
    const BASE: u64 = 36;
    const TMIN: u64 = 1;
    const TMAX: u64 = 26;
    const SKEW: u64 = 38;
    const DAMP: u64 = 700;
    let digit = |d: u64| -> char {
        char::from(if d < 26 {
            b'a' + d as u8
        } else {
            b'0' + (d - 26) as u8
        })
    };
    let adapt = |delta: u64, points: u64, first: bool| -> u64 {
        let mut delta = if first { delta / DAMP } else { delta / 2 };
        delta += delta / points;
        let mut k = 0;
        while delta > ((BASE - TMIN) * TMAX) / 2 {
            delta /= BASE - TMIN;
            k += BASE;
        }
        k + (BASE - TMIN + 1) * delta / (delta + SKEW)
    };
    let cps: Vec<u64> = input.chars().map(|c| u64::from(c as u32)).collect();
    let mut out: String = input.chars().filter(char::is_ascii).collect();
    let basic = out.len() as u64;
    if basic > 0 {
        out.push('-');
    }
    let (mut n, mut delta, mut bias, mut h) = (128u64, 0u64, 72u64, basic);
    while (h as usize) < cps.len() {
        let m = cps.iter().copied().filter(|&c| c >= n).min().unwrap_or(n);
        delta += (m - n) * (h + 1);
        n = m;
        for &c in &cps {
            if c < n {
                delta += 1;
            }
            if c == n {
                let mut q = delta;
                let mut k = BASE;
                loop {
                    let t = if k <= bias {
                        TMIN
                    } else if k >= bias + TMAX {
                        TMAX
                    } else {
                        k - bias
                    };
                    if q < t {
                        break;
                    }
                    out.push(digit(t + (q - t) % (BASE - t)));
                    q = (q - t) / (BASE - t);
                    k += BASE;
                }
                out.push(digit(q));
                bias = adapt(delta, h + 1, h == basic);
                delta = 0;
                h += 1;
            }
        }
        delta += 1;
        n += 1;
    }
    out
}

fn a_label_len(label: &str) -> usize {
    if label.is_ascii() {
        label.len()
    } else {
        "xn--".len() + punycode(label).len()
    }
}

/// UTS #39 §5.1 augmented script set; `None` is ALL (Common, Inherited).
fn augmented(cp: u32) -> Option<Vec<&'static str>> {
    let mut scripts: Vec<&'static str> = match value(t::SCRIPT_EXTENSIONS, cp) {
        Some(scx) => scx.to_vec(),
        None => vec![script(cp)],
    };
    if scripts == ["Zyyy"] || scripts == ["Zinh"] {
        return None;
    }
    let has = |scripts: &[&str], s: &str| scripts.contains(&s);
    let mut add = Vec::new();
    if has(&scripts, "Hani") {
        add.extend(["Hanb", "Jpan", "Kore"]);
    }
    if has(&scripts, "Hira") || has(&scripts, "Kana") {
        add.push("Jpan");
    }
    if has(&scripts, "Hang") {
        add.push("Kore");
    }
    if has(&scripts, "Bopo") {
        add.push("Hanb");
    }
    scripts.extend(add);
    scripts.sort_unstable();
    scripts.dedup();
    Some(scripts)
}

/// The resolved script set (UTS #39 §5.1), skipping the characters whose
/// augmented set has `without`. `None` is ALL.
fn resolved(cps: &[u32], without: Option<&str>) -> Option<Vec<&'static str>> {
    let mut resolved: Option<Vec<&'static str>> = None;
    for &cp in cps {
        let Some(scripts) = augmented(cp) else {
            continue;
        };
        if without.is_some_and(|w| scripts.contains(&w)) {
            continue;
        }
        resolved = Some(match resolved {
            None => scripts,
            Some(r) => r.into_iter().filter(|s| scripts.contains(s)).collect(),
        });
    }
    resolved
}

/// UTS #39 §5.2 highly restrictive: one script (Common and Inherited go
/// with any), or covered by Latin + Han + Hiragana + Katakana, by Latin +
/// Han + Bopomofo, or by Latin + Han + Hangul (computed as ICU does: the resolved
/// script set without the Latin characters has Jpan, Hanb or Kore).
fn is_highly_restrictive(cps: &[u32]) -> bool {
    match resolved(cps, None) {
        None => return true,
        Some(r) if !r.is_empty() => return true,
        Some(_) => {}
    }
    resolved(cps, Some("Latn"))
        .is_none_or(|r| r.iter().any(|s| matches!(*s, "Jpan" | "Hanb" | "Kore")))
}

/// RFC 5893 §2, rules 1 to 6, for one label.
fn bidi_ok(cps: &[u32]) -> bool {
    let classes: Vec<&str> = cps.iter().map(|&c| bidi_class(c)).collect();
    let (allowed, ends): (&[&str], &[&str]) = match classes.first() {
        Some(&("R" | "AL")) => (
            &["R", "AL", "AN", "EN", "ES", "CS", "ET", "ON", "BN", "NSM"],
            &["R", "AL", "EN", "AN"],
        ),
        Some(&"L") => (
            &["L", "EN", "ES", "CS", "ET", "ON", "BN", "NSM"],
            &["L", "EN"],
        ),
        _ => return false,
    };
    if classes.iter().any(|c| !allowed.contains(c)) {
        return false;
    }
    let last = classes
        .iter()
        .rev()
        .find(|&&c| c != "NSM")
        .unwrap_or(&classes[0]);
    ends.contains(last) && !(classes.contains(&"EN") && classes.contains(&"AN"))
}

/// Why a tag (already 1-64 bytes, without whitespace or controls) breaks
/// the label rules, or `None`. In order, for each label: not empty; no
/// hyphen at either end nor in positions 3 and 4; NFC; no leading
/// combining mark; every code point PVALID, or CONTEXTJ / CONTEXTO with
/// its rule; at most 63 bytes as an A-label; highly restrictive. Then, if
/// any character is R, AL or AN, every label follows the bidi rule (the
/// tag is a "bidi domain name"). The Python verifier has the same checks,
/// in the same order, with the same reasons.
pub fn tag_error(tag: &str) -> Option<String> {
    let labels: Vec<&str> = tag.split(TAG_SEPARATORS).collect();
    for label in &labels {
        if label.is_empty() {
            return Some("has an empty label (labels are separated by . / :)".into());
        }
        let cps: Vec<u32> = label.chars().map(|c| c as u32).collect();
        if label.starts_with('-') || label.ends_with('-') {
            return Some(format!("label {label:?} starts or ends with a hyphen"));
        }
        if cps.len() >= 4 && cps[2] == 0x2D && cps[3] == 0x2D {
            return Some(format!("label {label:?} has hyphens in positions 3 and 4"));
        }
        if !is_nfc(label) {
            return Some(format!("label {label:?} is not in NFC"));
        }
        if in_ranges(t::COMBINING_MARK, cps[0]) {
            return Some(format!("label {label:?} starts with a combining mark"));
        }
        for (i, &cp) in cps.iter().enumerate() {
            if in_ranges(t::IDNA_PVALID, cp) {
                continue;
            }
            let rule = if in_ranges(t::IDNA_CONTEXTJ, cp) {
                ("CONTEXTJ", contextj_ok(&cps, i))
            } else if in_ranges(t::IDNA_CONTEXTO, cp) {
                ("CONTEXTO", contexto_ok(&cps, i))
            } else if (0x41..=0x5A).contains(&cp) {
                return Some(format!(
                    "label {label:?} has an uppercase letter: tags are lowercase"
                ));
            } else {
                return Some(format!(
                    "label {label:?} has U+{cp:04X}, which IDNA2008 does not allow (Unicode {UNICODE_VERSION})"
                ));
            };
            if !rule.1 {
                return Some(format!(
                    "U+{cp:04X} in label {label:?} breaks its IDNA2008 context rule ({})",
                    rule.0
                ));
            }
        }
        if a_label_len(label) > MAX_A_LABEL_BYTES {
            return Some(format!(
                "label {label:?} is longer than {MAX_A_LABEL_BYTES} bytes as an A-label"
            ));
        }
        if !is_highly_restrictive(&cps) {
            return Some(format!(
                "label {label:?} mixes scripts (UTS #39 highly restrictive)"
            ));
        }
    }
    if tag
        .chars()
        .any(|c| matches!(bidi_class(c as u32), "R" | "AL" | "AN"))
    {
        for label in &labels {
            let cps: Vec<u32> = label.chars().map(|c| c as u32).collect();
            if !bidi_ok(&cps) {
                return Some(format!(
                    "label {label:?} breaks the IDNA2008 bidi rule (RFC 5893)"
                ));
            }
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The tables are the ones the generator wrote (same digest as the
    /// Python verifier's copy).
    #[test]
    fn tables_match_their_digest() {
        use sha2::{Digest, Sha256};
        let mut text = String::new();
        let ranges = |text: &mut String, name: &str, table: &[(u32, u32)]| {
            text.push_str(name);
            text.push('\n');
            for (lo, hi) in table {
                text.push_str(&format!("{lo:x} {hi:x}\n"));
            }
        };
        ranges(&mut text, "TEXT_FORBIDDEN", t::TEXT_FORBIDDEN);
        ranges(&mut text, "FORMAT", t::FORMAT);
        ranges(&mut text, "COMBINING_MARK", t::COMBINING_MARK);
        ranges(&mut text, "IDNA_PVALID", t::IDNA_PVALID);
        ranges(&mut text, "IDNA_CONTEXTJ", t::IDNA_CONTEXTJ);
        ranges(&mut text, "IDNA_CONTEXTO", t::IDNA_CONTEXTO);
        text.push_str("CCC\n");
        for (lo, hi, v) in t::CCC {
            text.push_str(&format!("{lo:x} {hi:x} {v:x}\n"));
        }
        text.push_str("DECOMPOSITION\n");
        for (cp, d) in t::DECOMPOSITION {
            let parts: Vec<String> = std::iter::once(cp)
                .chain(d.iter())
                .map(|c| format!("{c:x}"))
                .collect();
            text.push_str(&parts.join(" "));
            text.push('\n');
        }
        text.push_str("COMPOSITION\n");
        for (a, b, c) in t::COMPOSITION {
            text.push_str(&format!("{a:x} {b:x} {c:x}\n"));
        }
        for (name, table) in [
            ("BIDI_CLASS", t::BIDI_CLASS),
            ("JOINING_TYPE", t::JOINING_TYPE),
            ("SCRIPT", t::SCRIPT),
        ] {
            text.push_str(name);
            text.push('\n');
            for (lo, hi, v) in table {
                text.push_str(&format!("{lo:x} {hi:x} {v}\n"));
            }
        }
        text.push_str("SCRIPT_EXTENSIONS\n");
        for (lo, hi, v) in t::SCRIPT_EXTENSIONS {
            text.push_str(&format!("{lo:x} {hi:x} {}\n", v.join(" ")));
        }
        assert_eq!(
            hex::encode(Sha256::digest(text.as_bytes())),
            t::TABLES_SHA256
        );
        assert_eq!(UNICODE_VERSION, "16.0.0");
    }

    #[test]
    fn nfc_basics() {
        assert_eq!(nfc("e\u{301}"), "\u{e9}");
        assert!(is_nfc("fran\u{e7}ais"));
        assert!(!is_nfc("franc\u{327}ais"));
        // Hangul, algorithmic both ways.
        assert_eq!(nfc("\u{1100}\u{1161}\u{11a8}"), "\u{ac01}");
        assert!(is_nfc("\u{d55c}\u{ad6d}\u{c5b4}"));
        // Canonical ordering, and a composition exclusion stays decomposed.
        assert_eq!(nfc("a\u{323}\u{302}"), "\u{1ead}");
        assert_eq!(nfc("a\u{302}\u{323}"), "\u{1ead}");
        assert_eq!(nfc("\u{915}\u{93c}"), "\u{915}\u{93c}");
        // Singletons: the Angstrom sign becomes Å.
        assert_eq!(nfc("\u{212b}"), "\u{c5}");
    }

    #[test]
    fn punycode_rfc3492() {
        assert_eq!(punycode("bücher"), "bcher-kva");
        assert_eq!(punycode("ü"), "tda");
        assert_eq!(punycode("français"), "franais-xxa");
        assert_eq!(punycode("日本語"), "wgv71a119e");
        // RFC 3492 §7.1 (A) Arabic (Egyptian).
        assert_eq!(
            punycode(
                "\u{644}\u{64a}\u{647}\u{645}\u{627}\u{628}\u{62a}\u{643}\u{644}\u{645}\u{648}\u{634}\u{639}\u{631}\u{628}\u{64a}\u{61f}"
            ),
            "egbpdaj6bu4bxfgehfvwxn"
        );
    }

    #[test]
    fn tags() {
        for ok in [
            "lang:en",
            "cap:pdf",
            "code-review",
            "lang:fran\u{e7}ais",
            "topic:日本語のテキスト",
            "topic:한국어",
            "topic:Tシャツ".to_lowercase().as_str(),
            "l\u{b7}l",
            "\u{5e9}\u{5dc}\u{5d5}\u{5dd}:topic",
            "a/b.c:d",
            "\u{915}\u{94d}\u{200d}",
        ] {
            assert_eq!(tag_error(ok), None, "{ok}");
        }
        for (bad, why) in [
            ("Lang:en", "uppercase"),
            ("lang:franc\u{327}ais", "NFC"),
            ("p\u{430}ypal", "mixes scripts"),
            ("a::b", "empty label"),
            ("topic:-rust", "hyphen"),
            ("xn--abc", "positions 3 and 4"),
            ("a\u{200d}b", "CONTEXTJ"),
            ("topic:1\u{5e9}\u{5dc}\u{5d5}\u{5dd}", "bidi"),
            ("2024:\u{5e9}\u{5dc}\u{5d5}\u{5dd}", "bidi"),
            ("a\u{b7}b", "CONTEXTO"),
            ("\u{301}a", "combining mark"),
            ("a_b", "IDNA2008 does not allow"),
            ("\u{1ccf0}", "IDNA2008 does not allow"),
            (&"t".repeat(64), "A-label"),
        ] {
            let err = tag_error(bad).unwrap_or_default();
            assert!(err.contains(why), "{bad:?}: {err:?}");
        }
    }

    #[test]
    fn text_rules_and_display() {
        assert_eq!(forbidden_char("Report \u{a7db}"), None, "new in 16.0");
        assert_eq!(forbidden_char("a\u{200d}b\u{200c}"), None);
        for c in [
            '\u{202e}',
            '\u{e000}',
            '\u{2028}',
            '\u{2029}',
            '\u{fdd0}',
            '\u{10ffff}',
            '\u{a7cf}',
            '\u{378}',
        ] {
            assert_eq!(
                forbidden_char(&format!("x{c}")),
                Some(c),
                "U+{:04X}",
                c as u32
            );
        }
        assert_eq!(escape_format("a\u{202e}b\u{200d}"), "a\\u{202E}b\u{200d}");
        assert!(matches!(escape_format("plain"), Cow::Borrowed(_)));
        for name in [
            "CON",
            "nul.txt",
            "Lpt1.tar.gz",
            "com\u{b9}",
            "aux .md",
            "com0",
        ] {
            assert!(is_windows_reserved(name), "{name}");
        }
        for name in ["console", "nul-report.txt", "com10", "lpt", "x.nul"] {
            assert!(!is_windows_reserved(name), "{name}");
        }
    }
}
